"""Decoupling laboratory: the head says nothing, the tail says everything.

Constructs staged capture curves S(h, tau, r, k) -- head mass h held through
key r, then a linear ramp reaching the tolerance tau exactly at key k -- and
uses them to exhibit, in exact rational arithmetic:

  (1) one head mass compatible with arbitrarily many different knees,
      so no function maps top-8 mass to the knee;
  (2) two domain pairs with opposite signs of the head-mass/knee association,
      so the sign of a measured correlation carries no mechanistic content;
  (3) two domains identical on their first eight keys whose knees differ by
      any prescribed amount N.
"""

from __future__ import annotations

from fractions import Fraction as F
from typing import Callable, List, Tuple

CaptureCurve = Callable[[int], F]


def staged_profile(h: F, tau: F, r: int, k: int) -> CaptureCurve:
    step = (tau - h) / (F(k) - F(r))
    return lambda j: F(0) if j == 0 else min(F(1), h + F(max(j - r, 0)) * step)


def knee_at(cum: CaptureCurve, tau: F, bound: int = 100000) -> int:
    for k in range(bound + 1):
        if cum(k) >= tau:
            return k
    raise ValueError("knee not reached")


def one_head_many_knees(tau: F, h: F, targets: List[int]) -> List[Tuple[F, int]]:
    return [(h, knee_at(staged_profile(h, tau, 8, k), tau)) for k in targets]


def both_signs(tau: F) -> Tuple[Tuple[F, int, F, int], Tuple[F, int, F, int]]:
    P, Q = staged_profile(F(1, 2), tau, 8, 9), staged_profile(F(3, 4), tau, 8, 12)
    P2, Q2 = staged_profile(F(1, 2), tau, 8, 12), staged_profile(F(3, 4), tau, 8, 9)
    return ((P(8), knee_at(P, tau), Q(8), knee_at(Q, tau)),
            (P2(8), knee_at(P2, tau), Q2(8), knee_at(Q2, tau)))


def identical_heads_distant_knees(tau: F, N: int) -> Tuple[bool, int, int]:
    A = staged_profile(F(1, 2), tau, 8, 9)
    B = staged_profile(F(1, 2), tau, 8, 9 + N)
    same_head = all(A(j) == B(j) for j in range(9))
    return same_head, knee_at(A, tau), knee_at(B, tau)


def main() -> None:
    tau = F(9, 10)
    print(f"tolerance tau = {tau}\n")

    print("(1) one head mass, many knees")
    for h, k in one_head_many_knees(tau, F(1, 2), [9, 12, 25, 200, 5000]):
        print(f"    top-8 mass = {h}   ->   k* = {k}")
    print("    a function from head mass to knee cannot exist.\n")

    print("(2) both signs of the head-mass / knee association")
    (a, b, c, d), (e, f, g, h2) = both_signs(tau)
    print(f"    positive: {a} -> k* = {b}   and   {c} -> k* = {d}")
    print(f"    negative: {e} -> k* = {f}   and   {g} -> k* = {h2}")
    print("    the sign of a measured correlation is therefore uninformative.\n")

    print("(3) identical first eight keys, knees arbitrarily far apart")
    for N in (1, 10, 1000):
        same, ka, kb = identical_heads_distant_knees(tau, N)
        print(f"    N = {N:>5}:  heads identical? {same}   k* = {ka} vs {kb}")


if __name__ == "__main__":
    main()

